+package itemtracker;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadinbench.Application;
+import com.vaadinbench.views.ItemsView;
+import com.vaadinbench.views.MainLayout;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(classes = Application.class)
+public class ItemsViewTest extends SpringBrowserlessTest {
+
+    private ItemsView view;
+
+    @BeforeEach
+    void setup() {
+        view = navigate(ItemsView.class);
+    }
+
+    @Test
+    void shellShowsTitleInsideAppLayout() {
+        assertTrue($(MainLayout.class).exists());
+        assertEquals("Item Tracker", $(H2.class).first().getText());
+    }
+
+    @Test
+    void initialStateIsEmpty() {
+        assertEquals("Items", $(H1.class).first().getText());
+        assertEquals("Item", $(TextField.class).first().getLabel());
+        assertEquals("", $(TextField.class).first().getValue());
+        assertFalse($(ListItem.class).exists());
+        assertEquals("Items: 0", $(Span.class).first().getText());
+        assertTrue($(Button.class).withText("Add").first().isEnabled());
+        assertTrue($(Button.class).withText("Clear").first().isEnabled());
+    }
+
+    @Test
+    void addAppendsItemClearsFieldAndUpdatesCount() {
+        TextField field = $(TextField.class).first();
+        field.setValue("Apple");
+        $(Button.class).withText("Add").first().click();
+
+        assertEquals("", field.getValue());
+        assertEquals(1, $(ListItem.class).all().size());
+        assertEquals("Apple", $(ListItem.class).first().getText());
+        assertEquals("Items: 1", $(Span.class).first().getText());
+    }
+
+    @Test
+    void sameTextCanBeAddedTwiceAndKeepsOrder() {
+        TextField field = $(TextField.class).first();
+        Button add = $(Button.class).withText("Add").first();
+        field.setValue("A");
+        add.click();
+        field.setValue("B");
+        add.click();
+        field.setValue("A");
+        add.click();
+
+        assertEquals(3, $(ListItem.class).all().size());
+        assertEquals("A", $(ListItem.class).all().get(0).getText());
+        assertEquals("B", $(ListItem.class).all().get(1).getText());
+        assertEquals("A", $(ListItem.class).all().get(2).getText());
+        assertEquals("Items: 3", $(Span.class).first().getText());
+    }
+
+    @Test
+    void blankValueAddsNothingAndMarksFieldInvalid() {
+        TextField field = $(TextField.class).first();
+        Button add = $(Button.class).withText("Add").first();
+
+        add.click();
+        assertTrue(field.isInvalid());
+        assertFalse($(ListItem.class).exists());
+        assertEquals("Items: 0", $(Span.class).first().getText());
+
+        field.setValue("   ");
+        add.click();
+        assertTrue(field.isInvalid());
+        assertFalse($(ListItem.class).exists());
+        assertEquals("Items: 0", $(Span.class).first().getText());
+    }
+
+    @Test
+    void clearRemovesAllItemsAndItemsCanBeAddedAgain() {
+        TextField field = $(TextField.class).first();
+        Button add = $(Button.class).withText("Add").first();
+        field.setValue("X");
+        add.click();
+        field.setValue("Y");
+        add.click();
+
+        $(Button.class).withText("Clear").first().click();
+        assertFalse($(ListItem.class).exists());
+        assertEquals("Items: 0", $(Span.class).first().getText());
+
+        field.setValue("Z");
+        add.click();
+        assertEquals("Z", $(ListItem.class).first().getText());
+        assertEquals("Items: 1", $(Span.class).first().getText());
+    }
+}
